  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Model-first fourth-down and two-point policy",
      "recommendation": "Use a pregame win-probability decision chart as the default for fourth downs and two-point tries, with deviations limited to clearly identified game-specific information such as an injury or extreme weather. Be materially more aggressive than conventional coaching norms in favorable fourth-and-short and two-point situations.",
      "rationale": "Public win-probability research consistently finds that conventional NFL choices punt or kick too often in many high-leverage situations. Capturing the extra expected points and possession value raises win probability over a season.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.37,
          "interval_95_low": 0.01,
          "interval_95_high": 0.73,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The evidence direction is strong, and the remaining uncertainty is principally about decision volume, game-state selection, and team execution rather than a one-sided catastrophic failure mode."
        },
        "parameters": {
          "mu": 0.37,
          "sigma": 0.1837,
          "conversion_note": "normal(mu, sigma): mu = most_plausible_value = 0.37; sigma = (high - low) / 3.92 = (0.73 - 0.01) / 3.92 = 0.1837."
        },
        "consistency_check": "The most plausible value, 0.37, is inside [0.01, 0.73]. A normal distribution has unbounded signed support, so it permits both beneficial and harmful true effects; the displayed interval is approximate because parameters are rounded."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Pass-first neutral-down offense",
      "recommendation": "Increase efficient dropbacks and play-action passes on neutral early downs, especially first-and-10 and second-and-medium, instead of treating those downs as automatic run situations. Retain runs that exploit a demonstrated defensive box-count or personnel mismatch rather than running to preserve balance.",
      "rationale": "Public expected-points analyses have repeatedly found that early-down passing is more productive than conventional run-heavy sequencing, while favorable down-and-distance states improve later conversion and scoring chances.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.29,
          "interval_95_low": -0.13,
          "interval_95_high": 0.71,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The broad analytical direction is well supported, but the effect can vary sharply with quarterback protection, receiver quality, weather, and how much the current offense already passes efficiently. Heavy tails allow for unusually strong roster fit or a meaningful mismatch."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.29,
          "sigma": 0.178,
          "conversion_note": "student_t(nu, mu, sigma): nu = 7 and t_(0.975,7) approximately 2.36; mu = most_plausible_value = 0.29; sigma = (high - low) / (2 x 2.36) = (0.71 - (-0.13)) / 4.72 = 0.1780. Sigma is the t scale parameter."
        },
        "consistency_check": "The most plausible value, 0.29, is inside [-0.13, 0.71]. A Student t distribution has unbounded signed support, allowing the strategy to backfire for a poorly matched offense; the stated 95% interval is approximate."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Reduce discretionary third-down blitzes",
      "recommendation": "On obvious passing downs, reduce low-information blitzes and lean more often on four-man rushes or simulated pressure that preserve coverage numbers. Blitz selectively against quarterbacks and protections with demonstrated pressure-recognition weaknesses rather than as a default aggression signal.",
      "rationale": "Public pressure and EPA studies show that blitzing often trades coverage integrity for pressure without generating enough additional disruption to justify the cost, particularly against quarterbacks who identify and punish it quickly.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.17,
          "interval_95_low": -0.23,
          "interval_95_high": 0.57,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "There is public evidence for the average direction, but opponent quarterback style, pass-rush quality, and the defense's ability to execute simulated pressure create substantial uncertainty around a modest average gain."
        },
        "parameters": {
          "mu": 0.17,
          "sigma": 0.2041,
          "conversion_note": "normal(mu, sigma): mu = most_plausible_value = 0.17; sigma = (high - low) / 3.92 = (0.57 - (-0.23)) / 3.92 = 0.2041."
