        "belief_summaries": {
          "most_plausible_value": 0.04,
          "interval_95_low": -0.28,
          "interval_95_high": 0.36,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "This is a weak, film-driven candidate with a near-zero central estimate. Heavy tails reflect that a well-timed timeout could avert a major failure, while a wasted timeout can materially damage late-half clock management."
