        "distribution_family": {
          "name": "student_t",
          "justification": "This is a matchup-specific and uncertain tactic. It can remove a highly valuable scramble outlet, but it can also create more time for throws or weaken coverage, so substantial positive and negative outcomes remain plausible."
        },
